<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../../api/client'
import DialogPanel from '../../components/DialogPanel.vue'
import { duration, stateLabels, reportLabels, tone } from '../reports/presentation'
const route = useRoute(), project = ref(null), candidates = ref([]), email = ref(''), alias = ref(''), invitation = ref(''), error = ref(''), busy = ref(false), loading = ref(true), inviting = ref(false), query = ref(''), filter = ref('all'), inviteError = ref(''), copyStatus = ref('')
const counts = computed(() => ({ invited: candidates.value.length, running: candidates.value.filter(c => c.state === 'running').length, submitted: candidates.value.filter(c => c.state === 'submitted').length, reports: candidates.value.filter(c => c.report_status === 'ready').length }))
const filtered = computed(() => candidates.value.filter(c => (filter.value === 'all' || (filter.value === 'reports' ? c.report_status === 'ready' : c.state === filter.value)) && `${c.alias} ${c.email}`.toLowerCase().includes(query.value.trim().toLowerCase())))
async function load() { loading.value = true; error.value = ''; try { [project.value, candidates.value] = await Promise.all([api(`/projects/${route.params.id}`), api(`/projects/${route.params.id}/candidates`)]) } catch (e) { error.value = e.message } finally { loading.value = false } }
async function invite() {
  busy.value = true; inviteError.value = ''; copyStatus.value = ''
  try { const data = await api(`/projects/${route.params.id}/invitations`, { method: 'POST', body: { email: email.value, alias: alias.value } }); invitation.value = location.origin + data.path; email.value = ''; alias.value = ''; await load() }
  catch (e) { inviteError.value = e.message } finally { busy.value = false }
}
async function copy() { try { await navigator.clipboard.writeText(invitation.value); copyStatus.value = '초대 링크를 복사했습니다.' } catch { copyStatus.value = '아래 링크를 선택해 직접 복사해 주세요.' } }
function openInvite() { invitation.value = ''; inviteError.value = ''; copyStatus.value = ''; inviting.value = true }
onMounted(load)
</script>
<template><main class="page"><RouterLink to="/projects" class="back">평가 프로젝트 / 프로젝트 상세</RouterLink><div v-if="project" class="page-heading"><div><h1>{{ project.title }}</h1><p class="muted">{{ project.scenario_title }} · 제한 시간 {{ duration(project.duration_seconds) }}</p></div><button class="primary" @click="openInvite">＋ 지원자 초대</button></div><div v-if="project" class="chips"><span v-for="c in project.competencies" :key="c.id" class="badge">{{ c.name }}</span><span v-if="project.is_fixture" class="badge amber">개발용 · 실제 평가 아님</span></div><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="muted" role="status">지원자 현황을 불러오고 있습니다…</p><template v-if="project"><div class="stats-grid"><article v-for="s in [['초대한 지원자',counts.invited,'명'],['응시 중',counts.running,'명'],['응시 완료',counts.submitted,'명'],['리포트 준비',counts.reports,'건']]" :key="s[0]" class="stat-card"><span>{{ s[0] }}</span><strong>{{ s[1] }}<small>{{ s[2] }}</small></strong></article></div><section class="card"><div class="review-heading"><h2>지원자 관리</h2><button class="text-button" :disabled="loading" @click="load">새로고침</button></div><div class="filter-tabs"><button v-for="t in [['all','전체'],['running','응시 중'],['submitted','응시 완료'],['reports','리포트 준비']]" :key="t[0]" :class="{ active: filter === t[0] }" :aria-pressed="filter === t[0]" @click="filter = t[0]">{{ t[1] }}</button></div><div class="list-toolbar"><input v-model="query" class="search-field" aria-label="지원자 검색" placeholder="지원자 별칭 또는 이메일 검색"><span class="muted">{{ filtered.length }}명</span></div><p v-if="!candidates.length" class="empty-note">아직 초대한 지원자가 없습니다. 지원자를 초대해 평가를 시작하세요.</p><p v-else-if="!filtered.length" class="empty-note">조건에 맞는 지원자가 없습니다.</p><div v-else class="table-wrap"><table class="candidate-table"><thead><tr><th>지원자</th><th>이메일</th><th>응시 상태</th><th>분석 상태</th><th><span class="sr-only">상세 보기</span></th></tr></thead><tbody><tr v-for="c in filtered" :key="c.id"><td><div class="person-cell"><span class="person-avatar" aria-hidden="true">{{ c.alias.slice(0,1) }}</span><strong>{{ c.alias }}</strong></div></td><td class="muted">{{ c.email }}</td><td><span class="badge" :class="tone(c.state)">{{ stateLabels[c.state] || c.state }}</span></td><td><span v-if="c.report_status" class="badge" :class="tone(c.report_status)">{{ reportLabels[c.report_status] || c.report_status }}</span><span v-else class="muted">—</span></td><td><RouterLink v-if="c.session_id && c.report_status" class="text-button" :to="`/projects/${project.id}/reports/${c.session_id}`">{{ c.report_status === 'ready' ? '리포트 보기 →' : '분석 상태 보기 →' }}</RouterLink></td></tr></tbody></table></div></section></template><DialogPanel v-if="inviting" title="지원자 초대" @close="inviting = false"><p class="muted">지원자에게 전달할 초대 링크를 만듭니다.</p><form @submit.prevent="invite"><label>지원자 별칭<input v-model="alias" required maxlength="80" placeholder="지원자를 구분할 별칭"></label><label>지원자 이메일<input v-model="email" required type="email" placeholder="candidate@example.com"></label><p v-if="inviteError" class="error" role="alert">{{ inviteError }}</p><div v-if="invitation" class="notice"><p>초대 링크가 생성됐습니다. 72시간 안에 본인 계정으로 수락할 수 있습니다.</p><input :value="invitation" readonly aria-label="초대 링크" @focus="$event.target.select()"><button type="button" class="text-button" @click="copy">링크 복사</button><p role="status">{{ copyStatus }}</p><small>링크를 지원자에게 전달하세요. 이메일을 자동 발송하지 않습니다.</small></div><div class="form-footer"><button type="button" class="secondary" @click="inviting = false">닫기</button><button class="primary" :disabled="busy">{{ busy ? '생성 중…' : '초대 링크 만들기' }}</button></div></form></DialogPanel></main></template>
